/**
 * 翻页阅读器：正文排成左右两页，翻页时那一张纸真的立起来绕到另一边。
 *
 * 形态借自 turngl（MIT，WebGL 的 3D 翻书）——「一整张纸从书脊上掀起、
 * 转到对面落下」的过程照搬，但这里用 CSS 3D 的合页（perspective +
 * rotateY）而不是柱子面卷曲：正文是 DOM，字要能选中、单词要能点开词典、
 * 高亮要能落色，不能被烘成一张贴图。
 *
 * 分页规则：整段搬走，不切开段落 —— 标注存的是「段落下标 + 字符区间」，
 * 一段被劈成两页，偏移就对不上了。所以先把每段量一遍高，再按页容量贪心装。
 *
 * 翻页时画面分三层：
 *   双页 · 前进 —— 左边旧页不动；右半那张纸（正面＝本开右页，背面＝下一开左页）
 *                  向左翻过去，底下已经换成下一开的右页；
 *   双页 · 后退 —— 右页不动；左半那张纸向右翻回去，底下是上一开的左页；
 *   单页（窄屏）—— 退回配页栈的翻法：前进时整张纸向左翻走、底下露出下一页，
 *                  后退时上一页从左边摆回来盖住当前页。
 */
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";
import { useReducedMotion } from "motion/react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";
import { PageJump } from "./PageJump";
import "./reader-flip.css";

interface PageFlipReaderProps {
  /** 按顺序排好的段落块，一块一段，分页时整块搬走。 */
  leaves: ReactNode[];
  /** 排版参数变了（换书、换屏幕）就重新分页。 */
  measureKey: string;
  className?: string;
}

/** 一张纸翻过去要多久（毫秒）；「减少动态效果」时直接跳过去。 */
const TURN_MS = 760;
/** 窄到这个宽度就退回单页。 */
const SINGLE_PAGE_QUERY = "(max-width: 860px)";

interface FlipPage {
  /** 这一页放着第几个段落块。 */
  blocks: number[];
  /** 单独一段都装不下（少见）：这一页允许自己滚。 */
  tall: boolean;
}

interface Turn {
  dir: "fwd" | "bwd";
  from: number;
}

const samePacking = (a: FlipPage[], b: FlipPage[]) =>
  a.length === b.length &&
  a.every(
    (page, index) =>
      page.tall === b[index]!.tall &&
      page.blocks.length === b[index]!.blocks.length &&
      page.blocks.every((block, slot) => block === b[index]!.blocks[slot]),
  );

export function PageFlipReader({
  leaves,
  measureKey,
  className = "",
}: PageFlipReaderProps) {
  const reducedMotion = useReducedMotion();
  const measurerRef = useRef<HTMLDivElement>(null);
  const pointerRef = useRef<{ x: number; y: number; id: number } | null>(null);
  const [single, setSingle] = useState(
    () =>
      typeof window !== "undefined" &&
      window.matchMedia(SINGLE_PAGE_QUERY).matches,
  );
  const [pages, setPages] = useState<FlipPage[]>([]);
  const [spread, setSpread] = useState(0);
  const [turn, setTurn] = useState<Turn | null>(null);
  /** 挂上 is-turning 的那一帧：CSS 过渡要先看到起始状态才会动。 */
  const [lifted, setLifted] = useState(false);

  // ── 分页：量每一段的高，按页容量贪心装页 ─────────────────────────────
  const pack = useCallback(() => {
    const node = measurerRef.current;
    if (!node) return;
    const items = Array.from(node.children) as HTMLElement[];
    if (items.length === 0) return;
    const style = getComputedStyle(node);
    const capacity =
      node.clientHeight -
      (parseFloat(style.paddingTop) || 0) -
      (parseFloat(style.paddingBottom) || 0);
    if (capacity <= 0) return;
    const gap = parseFloat(getComputedStyle(items[0]!).marginBottom) || 0;

    const packed: FlipPage[] = [];
    let current: number[] = [];
    let used = 0;
    const flush = () => {
      if (current.length === 0) return;
      packed.push({ blocks: current, tall: used > capacity + 1 });
      current = [];
      used = 0;
    };
    items.forEach((item, index) => {
      const height = item.offsetHeight;
      if (current.length > 0 && used + gap + height > capacity) flush();
      if (current.length > 0) used += gap;
      current.push(index);
      used += height;
    });
    flush();
    setPages((previous) => (samePacking(previous, packed) ? previous : packed));
  }, []);

  useEffect(() => {
    const node = measurerRef.current;
    if (!node) return;
    pack();
    // 版心宽度一变（转屏、缩窗口）段落高就变了；段落自己变高（标注、中文
    // 对照）也要重量。量的是副本，这里量出来的高不会反过来影响副本，不会打转。
    const observer = new ResizeObserver(() => pack());
    observer.observe(node);
    Array.from(node.children).forEach((child) => observer.observe(child));
    void document.fonts?.ready.then(() => pack());
    return () => observer.disconnect();
  }, [pack, measureKey, leaves.length]);

  useEffect(() => {
    const query = window.matchMedia(SINGLE_PAGE_QUERY);
    const sync = () => setSingle(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  const total = pages.length;
  const per = single ? 1 : 2;
  // 双页时第 0 开只有右半页（书总是从右边翻开），所以页数要 +1 再折半。
  const spreadCount = single ? total : Math.ceil((total + 1) / 2);
  const leftIndex = single ? -1 : spread * 2 - 1;
  const rightIndex = single ? spread : spread * 2;

  // 内容换短了（换书）就退回还在的那一开。
  useLayoutEffect(() => {
    setSpread((current) => Math.min(current, Math.max(0, spreadCount - 1)));
  }, [spreadCount]);

  const canBack = spread > 0;
  const canForward = spread < spreadCount - 1;

  const pageAt = useCallback(
    (index: number): FlipPage | null =>
      index >= 0 && index < total ? pages[index]! : null,
    [pages, total],
  );

  // 落页。transitionend 和兜底计时器可能都想落同一张纸，只有「从哪一开翻出来的」
  // 还对得上才认，免得一下翻过去两页、落到没有页的地方。
  const commit = useCallback((finished: Turn) => {
    setSpread((current) => {
      if (current !== finished.from) return current;
      const next = finished.dir === "fwd" ? current + 1 : current - 1;
      return Math.max(0, next);
    });
    setTurn(null);
    setLifted(false);
  }, []);

  const turnPage = useCallback(
    (dir: "fwd" | "bwd") => {
      if (turn) return;
      if (dir === "fwd" && !canForward) return;
      if (dir === "bwd" && !canBack) return;
      if (reducedMotion) {
        commit({ dir, from: spread });
        return;
      }
      setTurn({ dir, from: spread });
      setLifted(false);
      // 两帧之后再挂 is-turning：让浏览器先看到「纸还躺着」这个起始状态。
      window.requestAnimationFrame(() =>
        window.requestAnimationFrame(() => setLifted(true)),
      );
    },
    [canBack, canForward, commit, reducedMotion, spread, turn],
  );

  // 页脚上写页码直接跳过去：翻页动画开着就不抢（等它落页再说）。
  const jumpToSpread = useCallback(
    (index: number) => {
      if (turn) return;
      setTurn(null);
      setLifted(false);
      setSpread(Math.min(Math.max(index, 0), Math.max(0, spreadCount - 1)));
    },
    [spreadCount, turn],
  );

  // 过渡结束就落页；万一 transitionend 没来（标签页被切走等），兜一个超时。
  useEffect(() => {
    if (!turn || !lifted) return;
    const timer = window.setTimeout(
      () => commit(turn),
      reducedMotion ? 0 : TURN_MS + 160,
    );
    return () => window.clearTimeout(timer);
  }, [commit, lifted, reducedMotion, turn]);

  // 键盘左右翻页：焦点在输入框里时不抢按键。
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      const target = event.target;
      if (
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        (target instanceof HTMLElement && target.isContentEditable)
      ) {
        return;
      }
      event.preventDefault();
      turnPage(event.key === "ArrowRight" ? "fwd" : "bwd");
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [turnPage]);

  // 触屏：横向划一下就是翻一页（纵向留给页面滚动）。
  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "touch") return;
    pointerRef.current = {
      x: event.clientX,
      y: event.clientY,
      id: event.pointerId,
    };
  };
  const onPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    const start = pointerRef.current;
    pointerRef.current = null;
    if (!start || start.id !== event.pointerId) return;
    const dx = event.clientX - start.x;
    const dy = event.clientY - start.y;
    if (Math.abs(dx) < 56 || Math.abs(dx) < Math.abs(dy)) return;
    turnPage(dx < 0 ? "fwd" : "bwd");
  };

  /** 一页纸：静止的书页、翻动那张纸的正面/背面，都用它。 */
  const renderPage = (page: FlipPage | null, side: "left" | "right") => (
    <div className={cn("reader-flip__page", `is-${side}`, page?.tall && "is-tall")}>
      {page?.blocks.map((block) => (
        <div className="reader-flip__block" key={block}>
          {leaves[block]}
        </div>
      ))}
      {page && page.tall ? (
        <span className="reader-flip__tall-hint" aria-hidden="true">
          ↕
        </span>
      ) : null}
      {page && page.blocks.length > 0 ? (
        <span className="reader-flip__folio" aria-hidden="true">
          {page.blocks[0]! + 1}
        </span>
      ) : null}
    </div>
  );

  // 翻动那张纸的正反面、底下的两层，按方向摆好。
  const layout = (() => {
    if (!turn) {
      return {
        variant: "" as const,
        front: null as FlipPage | null,
        back: null as FlipPage | null,
        underLeft: pageAt(leftIndex),
        underRight: pageAt(rightIndex),
      };
    }
    if (turn.dir === "fwd") {
      return {
        variant: "is-fwd" as const,
        front: pageAt(rightIndex),
        back: pageAt(rightIndex + per),
        underLeft: pageAt(leftIndex),
        // 纸一掀起，底下就是下一开的右页；纸落定前它已经被正面盖住过。
        underRight: pageAt(rightIndex + per),
      };
    }
    if (single) {
      return {
        variant: "is-return" as const,
        // 摆回来的这一页是上一页，正面朝外；背面还是当前页，飞过去时看得见。
        front: pageAt(spread - 1),
        back: pageAt(spread),
        underLeft: null,
        underRight: pageAt(spread),
      };
    }
    return {
      variant: "is-bwd" as const,
      front: pageAt(leftIndex),
      back: pageAt((turn.from - 1) * 2),
      underLeft: pageAt((turn.from - 1) * 2 - 1),
      underRight: pageAt(rightIndex),
    };
  })();

  return (
    <div
      className={cn("reader-flip", single && "is-single", className)}
      data-turning={turn ? "" : undefined}
    >
      {/* 量高度的那一份：和书页同宽同高，只是看不见。
          段落整块量、不切开；data-measure 让选区换算跳过这份副本。 */}
      <div className="reader-flip__measurer" ref={measurerRef} data-measure="">
        {leaves.map((leaf, index) => (
          <div className="reader-flip__block" key={index}>
            {leaf}
          </div>
        ))}
      </div>

      <div
        className="reader-flip__stage"
        onPointerDown={onPointerDown}
        onPointerUp={onPointerUp}
        onPointerCancel={() => {
          pointerRef.current = null;
        }}
      >
        <div className="reader-flip__book">
          {single ? null : renderPage(layout.underLeft, "left")}
          {renderPage(layout.underRight, "right")}

          {turn ? (
            <div
              className={cn(
                "reader-flip__leaf",
                layout.variant,
                lifted && "is-turning",
              )}
              onTransitionEnd={(event) => {
                if (event.propertyName === "transform") commit(turn);
              }}
            >
              <div className="reader-flip__face reader-flip__face--front">
                {renderPage(
                  layout.front,
                  layout.variant === "is-bwd" ? "left" : "right",
                )}
                <span className="reader-flip__sheen" aria-hidden="true" />
              </div>
              <div className="reader-flip__face reader-flip__face--back">
                {renderPage(
                  layout.back,
                  layout.variant === "is-fwd" && !single ? "left" : "right",
                )}
                <span
                  className="reader-flip__sheen is-back"
                  aria-hidden="true"
                />
              </div>
            </div>
          ) : null}
        </div>

        {/* 页边那一条空白就是翻页区：正文的字在版心里，不会被这一层挡住。 */}
        <button
          type="button"
          className="reader-flip__edge is-left"
          aria-label="上一页"
          disabled={!canBack}
          onClick={() => turnPage("bwd")}
        />
        <button
          type="button"
          className="reader-flip__edge is-right"
          aria-label="下一页"
          disabled={!canForward}
          onClick={() => turnPage("fwd")}
        />
      </div>

      <div className="reader-flip__nav">
        <button
          type="button"
          onClick={() => turnPage("bwd")}
          disabled={!canBack}
          aria-label="上一页"
        >
          <ChevronLeft size={15} />
        </button>
        {total === 0 ? (
          <span className="reader-flip__count">—</span>
        ) : (
          <PageJump
            className="reader-flip__count"
            page={spread + 1}
            total={spreadCount}
            unit=" 开"
            onJump={(target) => jumpToSpread(target - 1)}
          />
        )}
        <button
          type="button"
          onClick={() => turnPage("fwd")}
          disabled={!canForward}
          aria-label="下一页"
        >
          <ChevronRight size={15} />
        </button>
      </div>
    </div>
  );
}

export default PageFlipReader;
